using System.Data;
using System.Data.SqlTypes;
using Dapper;
using Microsoft.Data.SqlClient;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace SwiftExport.Application.Tests.Database;

/// <summary>仅以常量SELECT、等待及显式探针错误核验源驱动读取边界，不创建临时表或修改任何业务数据/结构。</summary>
[TestClass]
[DoNotParallelize]
[TestCategory("SqlServerSourceReadProtocolIntegration")]
public sealed class SqlServerSourceReadProtocolIntegrationTests
{
    /// <summary>空头读取仍推进下一结果，下一结果之前的技术错误不能被空头分支吞掉。</summary>
    [TestMethod]
    public async Task EmptyHeader_ObservesErrorBeforeNextResultMetadata()
    {
        using var connection = Open();
        var error = await Assert.ThrowsAsync<SqlException>(() => ReadEmptyHeader(connection,
            "SELECT CAST(NULL AS int) AS Value WHERE 1=0; THROW 51041,N'迁移只读下一结果探针',1;"));
        Assert.AreEqual(51041, error.Number);
        await Reusable(connection);
    }

    /// <summary>第二结果已有元数据后空头同步Dispose取消下游等待，不能假定尾部所有查询都执行。</summary>
    [TestMethod]
    public async Task EmptyHeader_CancelsUnreadTailAfterNextResultMetadata()
    {
        using var connection = Open();
        var header = await ReadEmptyHeader(connection,
            "SELECT CAST(NULL AS int) AS Value WHERE 1=0; SELECT 41 AS Value; WAITFOR DELAY '00:00:02'; THROW 51042,N'迁移只读未读尾部探针',1;");
        Assert.IsNull(header);
        await Reusable(connection);
    }

    /// <summary>源历史THROW在默认XACT_ABORT关闭的外层事务保持可回滚状态，记录业务异常与服务器事务影响边界。</summary>
    [TestMethod]
    public async Task SourceHistoryThrow_KeepsCallerTransactionUsableWithOriginalSessionDefaults()
    {
        using var connection = Open(); using var transaction = connection.BeginTransaction(IsolationLevel.Serializable);
        try
        {
            Assert.AreEqual(0, await connection.ExecuteScalarAsync<int>("SELECT CASE WHEN (16384 & @@OPTIONS)=16384 THEN 1 ELSE 0 END", transaction: transaction));
            var error = await Assert.ThrowsAsync<SqlException>(() => connection.ExecuteAsync("THROW 51001,N'迁移只读历史分类探针',1", transaction: transaction));
            Assert.AreEqual(51001, error.Number);
            Assert.AreEqual(1, await connection.ExecuteScalarAsync<int>("SELECT XACT_STATE()", transaction: transaction));
        }
        finally { transaction.Rollback(); }
        await Reusable(connection);
    }

    /// <summary>固定跨字段及随机UUID由真实源ORDER BY排序，与SqlGuid比对，为覆盖量的并列尾键提供事实证据。</summary>
    [TestMethod]
    public async Task SourceUuidOrdering_MatchesSqlGuidAcrossEveryByte()
    {
        using var connection = Open();
        var values = SortSamples();
        var expressions = string.Join(",", values.Select((_, index) => $"(@Id{index})"));
        var parameters = new DynamicParameters(); for (var i = 0; i < values.Count; i++) parameters.Add("Id" + i, values[i]);
        var actual = (await connection.QueryAsync<Guid>($"SELECT value FROM (VALUES {expressions}) AS ids(value) ORDER BY value", parameters)).ToArray();
        CollectionAssert.AreEqual(values.OrderBy(id => new SqlGuid(id)).ToArray(), actual);
        await Reusable(connection);
    }

    /// <summary>构造每个规范字节位置与多种跨字节权重，避免仅测正常UUID或恰好同序样例。</summary>
    internal static List<Guid> SortSamples()
    {
        var values = new List<Guid> { Guid.Empty, Guid.Parse("ffffffff-ffff-ffff-ffff-ffffffffffff") };
        for (var i = 0; i < 16; i++)
        {
            var bytes = new byte[16]; bytes[i] = 1; values.Add(new Guid(bytes)); bytes[i] = 128; values.Add(new Guid(bytes));
        }
        for (var i = 0; i < 64; i++) values.Add(Guid.NewGuid());
        return values;
    }

    /// <summary>保持源C#的同步using及空头分支，不用其他驱动或DisposeAsync代替待核验调用。</summary>
    private static async Task<Row?> ReadEmptyHeader(SqlConnection connection, string sql)
    {
        using var multi = await connection.QueryMultipleAsync(sql);
        var row = await multi.ReadSingleOrDefaultAsync<Row>();
        if (row is null) return null;
        return row;
    }

    /// <summary>只允许明确启用的源实例dv_next，只读SQL不从PG凭据推测SQLServer口令。</summary>
    private static SqlConnection Open()
    {
        var value = Environment.GetEnvironmentVariable("SWIFTEXPORT_SQL_SOURCE_READ_CONNECTION");
        if (Environment.GetEnvironmentVariable("SWIFTEXPORT_RUN_SQL_SOURCE_READ_TESTS") != "1" || string.IsNullOrWhiteSpace(value))
            Assert.Inconclusive("未显式启用源SQLServer只读协议探针，本项未运行。");
        SqlConnectionStringBuilder settings;
        try { settings = new(value); } catch (ArgumentException) { Assert.Fail("源只读连接格式无效。"); throw; }
        Assert.AreEqual("192.168.3.12", settings.DataSource); Assert.AreEqual("dv_next", settings.InitialCatalog.ToLowerInvariant());
        settings.ConnectTimeout = 10; settings.Pooling = false;
        var connection = new SqlConnection(settings.ConnectionString); connection.Open(); return connection;
    }

    /// <summary>每个探针后连接可查询且无外层事务；不清理表或回退现有成果。</summary>
    private static async Task Reusable(SqlConnection connection)
    {
        Assert.AreEqual(ConnectionState.Open, connection.State);
        Assert.AreEqual(0, await connection.ExecuteScalarAsync<int>("SELECT @@TRANCOUNT"));
        Assert.AreEqual(1, await connection.ExecuteScalarAsync<int>("SELECT 1"));
    }

    /// <summary>只承接常量空头，不读取或暴露任何业务行。</summary>
    private sealed class Row { public int Value { get; set; } }
}

using Dapper;
using Microsoft.Data.SqlClient;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace SwiftExport.Application.Tests.Database;

/// <summary>只读常量SELECT核验源Dapper实际NOT IN列表展开，避免把null列表猜成NOT IN(NULL)；不读写业务表或创建临时对象。</summary>
[TestClass, DoNotParallelize, TestCategory("SqlServerSourceReadProtocolIntegration")]
public sealed class SqlServerOutboundExclusionProtocolIntegrationTests
{
    /// <summary>与原请求相同的List&lt;Guid&gt;匿名参数，经实际SqlClient/Dapper验证空、null、重复和空身份的过滤。</summary>
    [TestMethod]
    [DataRow("empty", 2)] [DataRow("null", 2)] [DataRow("one", 1)] [DataRow("duplicate", 1)] [DataRow("empty-guid", 2)]
    public async Task ActualListExpansion_PreservesOriginalExcludedRows(string mode, int expected)
    {
        using var connection = Open(); var first = Guid.NewGuid(); var second = Guid.NewGuid();
        List<Guid>? excluded = mode switch
        { "null" => null, "one" => [first], "duplicate" => [first, first], "empty-guid" => [Guid.Empty], _ => [] };
        var result = await connection.ExecuteScalarAsync<int>("""
            SELECT COUNT(*) FROM (VALUES (CAST(@First AS uniqueidentifier)),(CAST(@Second AS uniqueidentifier))) b(ProductId)
            WHERE b.ProductId NOT IN @ExcludedProductIds;
            """, new { First = first, Second = second, ExcludedProductIds = excluded });
        Assert.AreEqual(expected, result);
        Assert.AreEqual(0, await connection.ExecuteScalarAsync<int>("SELECT @@TRANCOUNT"));
        Assert.AreEqual(1, await connection.ExecuteScalarAsync<int>("SELECT 1"));
    }

    /// <summary>严格源只读门禁且无默认凭据，只开放已授权SQL Server实例dv_next。</summary>
    private static SqlConnection Open()
    {
        var value = Environment.GetEnvironmentVariable("SWIFTEXPORT_SQL_SOURCE_READ_CONNECTION");
        if (Environment.GetEnvironmentVariable("SWIFTEXPORT_RUN_SQL_SOURCE_READ_TESTS") != "1" || string.IsNullOrWhiteSpace(value))
            Assert.Inconclusive("未显式启用源SQL Server只读列表探针，本项未运行。");
        SqlConnectionStringBuilder settings;
        try { settings = new(value); } catch (ArgumentException) { Assert.Fail("源只读连接格式无效。"); throw; }
        Assert.AreEqual("192.168.3.12", settings.DataSource); Assert.AreEqual("dv_next", settings.InitialCatalog.ToLowerInvariant());
        settings.Pooling = false; settings.ConnectTimeout = 10;
        var connection = new SqlConnection(settings.ConnectionString); connection.Open(); return connection;
    }
}

using System.Data.SqlTypes;
using Dapper;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using SwiftExport.Infrastructure.Data;
using SwiftExport.Infrastructure.Repositories.Base;

namespace SwiftExport.Application.Tests.Database;

/// <summary>主控在真实PG核验Trace冻结覆盖数组及SQLServer UUID尾键；仅常量读取，不代替仓储完整Trace验收。</summary>
[TestClass]
[DoNotParallelize]
[TestCategory("PostgreSqlIntegration")]
public sealed class PostgreSqlTraceReadProtocolIntegrationTests
{
    /// <summary>PG UUID规范字节调整后与已实测的SqlGuid顺序一致；用于会改变覆盖归属的窗口并列尾键。</summary>
    [TestMethod]
    public async Task CoverageTieBreaker_PreservesSourceUuidBytePriority()
    {
        using var session = Open(); var values = SqlServerSourceReadProtocolIntegrationTests.SortSamples();
        var parameters = new PostgreSqlParameters(); parameters.AddIds("Ids", values);
        var actual = (await session.Connection.QueryAsync<Guid>("""
            SELECT value FROM unnest(CAST(@Ids AS uuid[])) AS ids(value)
            ORDER BY ARRAY[
                get_byte(uuid_send(value),10),get_byte(uuid_send(value),11),get_byte(uuid_send(value),12),
                get_byte(uuid_send(value),13),get_byte(uuid_send(value),14),get_byte(uuid_send(value),15),
                get_byte(uuid_send(value),8),get_byte(uuid_send(value),9),get_byte(uuid_send(value),7),get_byte(uuid_send(value),6),
                get_byte(uuid_send(value),5),get_byte(uuid_send(value),4),get_byte(uuid_send(value),3),get_byte(uuid_send(value),2),
                get_byte(uuid_send(value),1),get_byte(uuid_send(value),0)]
            """, parameters)).ToArray();
        CollectionAssert.AreEqual(values.OrderBy(id => new SqlGuid(id)).ToArray(), actual);
        Assert.IsNull(session.Transaction);
    }

    /// <summary>等长冻结数组按位置展开，空集合、全未知、重复目标和nullable数值保持配对及SQL聚合含义。</summary>
    [TestMethod]
    [DataRow("empty")]
    [DataRow("null")]
    [DataRow("paired")]
    public async Task FrozenCoverageRelation_BindsTypedArraysAndPreservesUnknownValues(string mode)
    {
        using var session = Open(); var target = Guid.NewGuid(); var first = Guid.NewGuid(); var second = Guid.NewGuid();
        var ids = mode == "empty" ? Array.Empty<Guid>() : new[] { first, second };
        var targets = mode == "empty" ? Array.Empty<Guid>() : new[] { target, target };
        var quantities = mode switch { "empty" => Array.Empty<decimal?>(), "null" => new decimal?[] { null, null }, _ => new decimal?[] { 6m, 1m } };
        var parameters = new PostgreSqlParameters(); parameters.AddIds("LinkIds", ids); parameters.AddIds("TargetIds", targets);
        parameters.Add("Quantities", quantities); parameters.Add("First", first); parameters.Add("Second", second);
        var row = await session.Connection.QuerySingleAsync<CoverageSummary>("""
            WITH frozen AS MATERIALIZED (
                SELECT * FROM unnest(CAST(@LinkIds AS uuid[]),CAST(@TargetIds AS uuid[]),CAST(@Quantities AS numeric[]))
                    AS coverage(link_id,target_line_id,coverage_qty))
            SELECT COUNT(*)::integer AS "Count",COUNT(*) FILTER (WHERE coverage_qty IS NULL)::integer AS "UnknownCount",
                   SUM(coverage_qty) AS "Total",COUNT(DISTINCT target_line_id)::integer AS "TargetCount",
                   (SELECT coverage_qty FROM frozen WHERE link_id=@First) AS "First",
                   (SELECT coverage_qty FROM frozen WHERE link_id=@Second) AS "Second" FROM frozen
            """, parameters);
        Assert.AreEqual(ids.Length, row.Count); Assert.AreEqual(mode == "null" ? 2 : 0, row.UnknownCount);
        Assert.AreEqual(mode == "empty" ? 0 : 1, row.TargetCount);
        Assert.AreEqual(mode == "paired" ? 7m : (decimal?)null, row.Total);
        Assert.AreEqual(mode == "paired" ? 6m : (decimal?)null, row.First);
        Assert.AreEqual(mode == "paired" ? 1m : (decimal?)null, row.Second);
        Assert.IsNull(session.Transaction);
    }

    /// <summary>只借用既有严格故障库门禁，不设置默认凭据、不操作源库/备份或创建数据结构。</summary>
    private static DbSession Open() => new(new PostgreSqlConnectionFactory(PostgreSqlIntegrationEnvironment.GetFailureConnectionString()));

    /// <summary>局部常量聚合投影，检验NULL区别，不变更公共Trace DTO或业务数量算法。</summary>
    private sealed class CoverageSummary
    {
        public int Count { get; set; }
        public int UnknownCount { get; set; }
        public int TargetCount { get; set; }
        public decimal? Total { get; set; }
        public decimal? First { get; set; }
        public decimal? Second { get; set; }
    }
}

using Mapster;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using SwiftExport.Application.Interfaces.ForExcel;
using SwiftExport.Application.Tests.Procurement;
using SwiftExport.Contracts.Common;
using SwiftExport.Contracts.DTOs.Errors;
using SwiftExport.Contracts.DTOs.ForExcel.PurchaseOrders;
using SwiftExport.Core.Interfaces.Procurement;
namespace SwiftExport.Application.Tests.ForExcel;

/// <summary>在唯一隔离 LocalDB 中验证采购导入检验、真实落库、重放、重验和回滚，不连接业务库。</summary>
[TestClass,DoNotParallelize]
public sealed class ForExcelPurchaseOrderSqlTests
{
    private IndependentProcurementSqlFixture db = default!;
    private Guid customerProductId;

    /// <summary>仅显式开启时建立本测试专属库和客户型号关联。</summary>
    [TestInitialize]
    public async Task InitializeAsync()
    {
        if (Environment.GetEnvironmentVariable("SWIFTEXPORT_RUN_SQL_TESTS") != "1")
            Assert.Inconclusive("设置 SWIFTEXPORT_RUN_SQL_TESTS=1 后运行隔离 LocalDB 测试。");
        db=new();await db.InitializeAsync();customerProductId=Guid.NewGuid();
        await db.ExecuteAsync("""
            INSERT dbo.CustomerProduct(Uid,CustomerId,CustomerCode,SkuId,CustomerSku,LinkSku,IsActive)
            VALUES(@Uid,@CustomerId,N'TEST-C',@ProductId,N'AQ1710BGM',N'AT421100BGM',1);
            """,new{Uid=customerProductId,db.CustomerId,db.ProductId});
    }

    /// <summary>无论成功或失败，只清理本实例建立的测试数据库。</summary>
    [TestCleanup]
    public async Task CleanupAsync()
    {
        if (db is not null) await db.DisposeAsync();
    }

    /// <summary>从实际检查到创建、读取，保留所有商业快照，生成独立草稿且不创建 Link。</summary>
    [TestMethod]
    public async Task CheckCreateAndReadPersistCommercialSnapshots()
    {
        var request=Request();
        var check=await db.InScopeAsync(p=>p.GetRequiredService<IForExcelPurchaseOrderService>().CheckAsync(request));
        Assert.IsTrue(check.Success,check.Message);Assert.IsTrue(check.Data.CanSave);
        Assert.AreEqual(db.ProductId,check.Data.Lines[0].Product.ProductId);
        Assert.AreEqual("TEST-FG",check.Data.Lines[0].Product.Sku);
        var command=db.CreateCommand();
        request.Header.Adapt(command);
        command.CustomerId=db.CustomerId;command.SupplierId=db.SupplierId;
        request.Lines[0].Adapt(command.Lines[0]);
        command.Lines[0].ProductId=check.Data.Lines[0].Product.ProductId!.Value;
        command.Lines[0].SelectedCustomerProductId=customerProductId;
        var created=await db.CreateAsync(command);Assert.IsTrue(created.Success,created.Message);
        var replay=await db.CreateAsync(command);Assert.IsTrue(replay.Success,replay.Message);
        Assert.AreEqual(created.Data.PurchaseOrderId,replay.Data.PurchaseOrderId);
        var detail=await db.InScopeAsync(p=>p.GetRequiredService<IProcurementOrderQueryRepository>().GetDetailAsync(created.Data.PurchaseOrderId,default));
        Assert.IsNotNull(detail);Assert.AreEqual("AT260820DQ",detail.BoNo);
        Assert.AreNotEqual(detail.BoNo,detail.OrderNo);Assert.AreEqual("Order 47",detail.CustomerPoNo);
        Assert.AreEqual("Tony",detail.SalesPerson);Assert.AreEqual("Paggie",detail.PurchasePerson);
        Assert.AreEqual("G1/2",detail.InletHoseType);Assert.AreEqual("Neoperl",detail.AeratorType);
        Assert.AreEqual("不打托",detail.PalletType);Assert.AreEqual("客户定制",detail.BoxType);
        Assert.AreEqual("标贴",detail.LabelType);Assert.AreEqual("说明书",detail.InstructionManualType);
        Assert.AreEqual("外箱",detail.CartonType);Assert.AreEqual("AQUATEK",detail.LogoType);
        Assert.AreEqual(request.Header.ReplyDate,detail.ReplyDate);
        Assert.AreEqual(0.95m,detail.DiscountRate);Assert.AreEqual(100m,detail.DiscountAmount);
        Assert.AreEqual("只记录",detail.DiscountRemark);
        var line=detail.Lines.Single();
        Assert.AreEqual("AQ1710BGM",line.CustomerSku);Assert.AreEqual("AT421100BGM",line.LinkSku);
        Assert.AreEqual("Excel工厂型号",line.SupplierSku);Assert.AreEqual("Excel描述",line.DescriptionZh);
        Assert.AreEqual("Excel颜色",line.FinishZh);Assert.AreEqual("Excel配置",line.FeaturesZh);
        Assert.AreEqual(116m,line.UnitPrice);Assert.AreEqual(4176m,line.UnitAmount);
        Assert.AreEqual(4176m,detail.CnyTotalAmount);Assert.AreEqual(line.Quantity,
